INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3650, 'internal control', '/ɪnˈtɜːrnəl kənˈtroʊl/', 'noun', '{"zh-TW":["內部控制"],"en":["policies and procedures to ensure accuracy, compliance, and fraud prevention"]}', NULL, 'strengthen internal controls / internal control framework / internal control weakness', '[{"en":"Strong internal controls reduce the risk of financial misstatement.","zh-TW":"強大的內部控制降低了財務錯報的風險。"},{"en":"The auditors identified a weakness in the internal controls.","zh-TW":"審計師識別了內部控制的弱點。"}]', '{"plural":"internal controls"}', NULL, 5, 3650, NULL),
(3651, 'internal controls', '/ɪnˈtɜːrnəl kənˈtroʊlz/', 'noun', '{"zh-TW":["內部控制"],"en":["processes and procedures designed to ensure accuracy and compliance in operations"]}', NULL, 'strengthen internal controls / review internal controls', '[{"en":"Strong internal controls reduce the risk of fraud and error.","zh-TW":"強有力的內部控制降低了欺詐和錯誤的風險。"},{"en":"Auditors evaluate the effectiveness of internal controls during their review.","zh-TW":"審計師在審查期間評估內部控制的有效性。"}]', NULL, NULL, 5, 3651, NULL),
(3652, 'internal financing', '/ɪnˈtɜːrnəl ˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["內部融資"],"en":["using retained profits to fund investment rather than external borrowing"]}', NULL, 'use internal financing / internal financing strategy', '[{"en":"The company relied on internal financing to avoid taking on more debt.","zh-TW":"公司依靠內部融資以避免承擔更多債務。"},{"en":"Internal financing is cheaper but limits the scale of investment.","zh-TW":"內部融資成本更低，但限制了投資規模。"}]', NULL, NULL, 5, 3652, NULL),
(3653, 'internal rate of return', '/ɪnˈtɜːrnəl reɪt əv rɪˈtɜːrn/', 'noun', '{"zh-TW":["內部收益率"],"en":["the discount rate at which NPV of an investment equals zero"]}', NULL, 'calculate internal rate of return / high internal rate of return', '[{"en":"The project''s internal rate of return exceeded the cost of capital.","zh-TW":"項目的內部收益率超過了資本成本。"},{"en":"Investors compare IRR to their required return to evaluate investments.","zh-TW":"投資者將內部收益率與所需回報率比較以評估投資。"}]', '{"abbreviation":"IRR"}', NULL, 5, 3653, NULL),
(3654, 'international', 'ˌɪntərˈnæʃənəl', 'adjective', '{"zh-TW":["國際的；跨國的","跨境的"],"en":["involving more than one country","global"]}', NULL, 'international business/international team', '[{"en":"We expanded into international markets.","zh-TW":"我們擴展到了國際市場。"}]', '{"noun":"internationalization","adverb":"internationally"}', NULL, 5, 3654, NULL),
(3655, 'international trade finance', '/ˌɪntəˈnæʃənl treɪd ˈfaɪnæns/', 'noun', '{"zh-TW":["國際貿易融資"],"en":["financial instruments and products that facilitate international business transactions"]}', NULL, 'access international trade finance / international trade finance products', '[{"en":"Letters of credit are core tools in international trade finance.","zh-TW":"信用狀是國際貿易融資的核心工具。"},{"en":"International trade finance reduces payment risk for cross-border transactions.","zh-TW":"國際貿易融資降低了跨境交易的付款風險。"}]', NULL, NULL, 5, 3655, NULL),
(3656, 'internet', '/ˈɪntərnɛt/', 'noun', '{"zh-TW":["網路"],"en":["the global network connecting computers"]}', NULL, 'internet access / on the internet', '[{"en":"Do you have internet access?","zh-TW":"你能上網嗎？"},{"en":"I found it on the internet.","zh-TW":"我在網路上找到的。"}]', NULL, NULL, 3, 3656, NULL),
(3657, 'internet of things', '/ˈɪntənet əv θɪŋz/', 'noun', '{"zh-TW":["物聯網"],"en":["the network of physical devices connected to the internet that collect and share data"]}', NULL, 'internet of things device / internet of things platform / implement internet of things', '[{"en":"The internet of things is transforming manufacturing through smart sensors.","zh-TW":"物聯網正在通過智慧感測器改變製造業。"},{"en":"Security remains a major concern in large-scale internet of things deployments.","zh-TW":"在大規模物聯網部署中，安全性仍是一個主要問題。"}]', NULL, NULL, 5, 3657, NULL),
(3658, 'internship', '/ˈɪntɜːrnʃɪp/', 'noun', '{"zh-TW":["實習；實習生計劃"],"en":["a period of practical work experience in a company"]}', NULL, 'summer internship / complete an internship', '[{"en":"She completed a summer internship at a top law firm.","zh-TW":"她在一家頂級律師事務所完成了暑期實習。"},{"en":"Internships provide valuable real-world experience.","zh-TW":"實習提供了寶貴的實際工作經驗。"}]', '{"noun":"intern","verb":"intern"}', NULL, 4, 3658, NULL),
(3659, 'interoperability', '/ˌɪntərˌɒpərəˈbɪlɪti/', 'noun', '{"zh-TW":["互操作性；互通性"],"en":["the ability of different systems or organizations to work together"]}', NULL, 'ensure interoperability / system interoperability / data interoperability', '[{"en":"Interoperability between healthcare software systems enables seamless data sharing.","zh-TW":"醫療軟件系統之間的互操作性實現了無縫的數據共享。"},{"en":"The new standard requires interoperability across all certified devices.","zh-TW":"新標準要求所有經認證設備之間具備互操作性。"}]', '{"adjective":"interoperable"}', NULL, 5, 3659, NULL),
(3660, 'interpersonal skills', '/''ɪntəˌpɜːrsənəl skɪlz/', 'noun', '{"zh-TW":["人際技能；人際溝通能力"],"en":["the abilities used to interact with others effectively, including communication and social skills"]}', NULL, 'develop interpersonal skills / strong interpersonal skills / interpersonal skills training', '[{"en":"Strong interpersonal skills are essential for anyone working in a team environment.","zh-TW":"強大的人際技能對在團隊環境中工作的任何人都是必不可少的。"},{"en":"Interpersonal skills such as empathy and active listening improve workplace relationships.","zh-TW":"同理心和積極傾聽等人際技能改善了工作場所的關係。"}]', NULL, NULL, 5, 3660, NULL),
(3661, 'interpolate', '/ɪnˈtɜːrpəleɪt/', 'verb', '{"zh-TW":["插值；插入"],"en":["to estimate a value between two known values; to insert new material"]}', NULL, 'interpolate data / interpolate values / interpolate missing points', '[{"en":"The algorithm interpolates missing data points in the time series.","zh-TW":"算法對時間序列中的缺失數據點進行插值。"},{"en":"We can interpolate temperature readings between two measurement stations.","zh-TW":"我們可以在兩個測量站之間對溫度讀數進行插值。"}]', '{"noun":"interpolation","adjective":"interpolated"}', NULL, 4, 3661, NULL),
(3662, 'interpolation', '/ɪnˌtɜːrpəˈleɪʃən/', 'noun', '{"zh-TW":["插值；插入"],"en":["the action of estimating unknown values between known ones"]}', NULL, 'linear interpolation / data interpolation / interpolation method', '[{"en":"Interpolation is used to estimate values between two data points.","zh-TW":"插值用於估算兩個數據點之間的值。"},{"en":"The graph uses interpolation to fill in gaps in the time series.","zh-TW":"圖表使用插值填補時間序列中的空缺。"}]', '{"verb":"interpolate","adjective":"interpolated"}', NULL, 5, 3662, NULL),
(3663, 'interpret', '/ɪnˈtɜːrprɪt/', 'verb', '{"zh-TW":["解釋；口譯"],"en":["to explain the meaning of; to translate orally"]}', NULL, 'interpret data/results / interpret for someone', '[{"en":"The data can be interpreted in different ways.","zh-TW":"數據可以有不同的解讀方式。"},{"en":"She interpreted for the foreign delegates.","zh-TW":"她為外國代表做口譯。"}]', '{"noun":"interpretation, interpreter","verb":"interpret"}', NULL, 3, 3663, NULL),
(3664, 'interrupt', '/ˌɪntəˈrʌpt/', 'noun', '{"zh-TW":["中斷"],"en":["a signal that prompts the operating system to take immediate action"]}', NULL, 'hardware interrupt / software interrupt / interrupt handler', '[{"en":"A hardware interrupt signals the CPU to stop and handle an urgent event.","zh-TW":"硬體中斷通知CPU停下來處理緊急事件。"},{"en":"Interrupt-driven programming is more efficient than polling for event handling.","zh-TW":"中斷驅動程式設計比輪詢更有效地處理事件。"}]', '{"verb":"interrupt","adjective":"interrupted"}', NULL, 3, 3664, NULL),
(3665, 'intersection', '/ˌɪntərˈsekʃn/', 'noun', '{"zh-TW":["交叉口；交集"],"en":["the point where two things cross; a shared area"]}', NULL, 'at the intersection of / road intersection', '[{"en":"Our product sits at the intersection of technology and design.","zh-TW":"我們的產品位於技術和設計的交集處。"},{"en":"Turn left at the next intersection.","zh-TW":"在下一個路口左轉。"}]', '{"noun":"intersection","verb":"intersect"}', NULL, 4, 3665, NULL),
(3666, 'intersectionality', '/ˌɪntəˌsekʃəˈnælɪti/', 'noun', '{"zh-TW":["交叉性；交織性"],"en":["the interconnected nature of social categorizations such as race, class, and gender"]}', NULL, 'intersectionality framework / apply intersectionality / intersectionality analysis', '[{"en":"Intersectionality shows that discrimination affects people differently based on multiple identities.","zh-TW":"交叉性表明歧視根據多種身份對人的影響有所不同。"},{"en":"Feminist scholars use intersectionality to analyze overlapping systems of oppression.","zh-TW":"女性主義學者使用交叉性分析相互重疊的壓迫系統。"}]', '{"adjective":"intersectional"}', NULL, 5, 3666, NULL),
(3667, 'intertextuality', '/ˌɪntəˌtekstʃuˈælɪti/', 'noun', '{"zh-TW":["互文性；文本間的相互關聯"],"en":["the relationship between texts and their influence on each other"]}', NULL, 'explore intertextuality / rich intertextuality / analyze intertextuality', '[{"en":"The novel''s intertextuality rewards readers familiar with classical mythology.","zh-TW":"這部小說的互文性獎勵了熟悉古典神話的讀者。"},{"en":"Intertextuality is a central feature of postmodern literature.","zh-TW":"互文性是後現代文學的核心特徵。"}]', '{"adjective":"intertextual","adverb":"intertextually"}', NULL, 5, 3667, NULL),
(3668, 'interval training', '/''ɪntərvəl ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["間歇訓練"],"en":["a type of training that alternates between periods of high-intensity exercise and rest or low-intensity exercise"]}', NULL, 'high-intensity interval training / interval training session / benefit of interval training', '[{"en":"High-intensity interval training burns more calories in less time than steady-state cardio.","zh-TW":"高強度間歇訓練比穩定有氧運動在更短時間內燃燒更多卡路里。"},{"en":"She incorporates interval training twice a week to improve her speed and endurance.","zh-TW":"她每週進行兩次間歇訓練以提高速度和耐力。"}]', NULL, NULL, 5, 3668, NULL),
(3669, 'intervene', '/ˌɪntərˈviːn/', 'verb', '{"zh-TW":["干預；介入"],"en":["to become involved in a situation to change the outcome"]}', NULL, 'intervene in a dispute/conflict', '[{"en":"The government intervened to stabilize the economy.","zh-TW":"政府介入以穩定經濟。"},{"en":"A manager had to intervene in the dispute.","zh-TW":"一位經理不得不介入糾紛。"}]', '{"noun":"intervention","verb":"intervene"}', NULL, 3, 3669, NULL),
(3670, 'interventionism', '/ˌɪntɜːˈvenʃənɪzəm/', 'noun', '{"zh-TW":["干預主義"],"en":["the practice of a government intervening in economic or foreign affairs"]}', NULL, 'economic interventionism / state interventionism / criticism of interventionism', '[{"en":"State interventionism in the economy was used to protect struggling industries.","zh-TW":"政府對經濟的干預主義被用來保護陷入困境的行業。"},{"en":"Military interventionism was debated intensely following the collapse of the ceasefire.","zh-TW":"在停火崩潰後，軍事干預主義引發了激烈辯論。"}]', '{"adjective":"interventionist","noun2":"interventionist"}', NULL, 5, 3670, NULL),
(3671, 'interview', '/ˈɪntərvjuː/', 'noun, verb', '{"zh-TW":["面試；訪談","面試；採訪"],"en":["a formal meeting for assessment; a conversation for media","to conduct an interview"]}', NULL, 'job interview / conduct an interview', '[{"en":"She has a job interview tomorrow morning.","zh-TW":"她明天早上有一場工作面試。"},{"en":"The journalist interviewed the CEO.","zh-TW":"記者採訪了執行長。"}]', '{"noun":"interview, interviewer, interviewee","verb":"interview"}', NULL, 3, 3671, 143),
(3672, 'intonation', '/''ɪntəˌneɪʃən/', 'noun', '{"zh-TW":["語調；聲調"],"en":["the rise and fall of the voice in speaking, which can change the meaning of what is said"]}', NULL, 'rising intonation / falling intonation / correct intonation', '[{"en":"Using rising intonation at the end of a sentence often indicates a question.","zh-TW":"在句子末尾使用上升語調通常表示疑問。"},{"en":"Her intonation and tone of voice conveyed warmth and confidence.","zh-TW":"她的語調和聲音傳達出溫暖和自信。"}]', NULL, NULL, 4, 3672, NULL),
(3673, 'intracompany transaction', '/ˌɪntrəˈkʌmpəni trænˈzækʃən/', 'noun', '{"zh-TW":["公司內部交易"],"en":["a financial transaction between different subsidiaries of the same corporate group"]}', NULL, 'eliminate intracompany transactions / intracompany transaction pricing', '[{"en":"Intracompany transactions must be eliminated when consolidating group accounts.","zh-TW":"在合並集團帳目時，公司內部交易必須被消除。"},{"en":"Transfer pricing rules apply to intracompany transactions across different tax jurisdictions.","zh-TW":"轉移定價規則適用於跨不同稅務司法管轄區的公司內部交易。"}]', NULL, NULL, 5, 3673, NULL),
(3674, 'intravenous', '/ˌɪntrəˈviːnəs/', 'adjective', '{"zh-TW":["靜脈注射的；靜脈內的"],"en":["administered directly into a vein"]}', NULL, 'intravenous drip / intravenous medication', '[{"en":"The patient received intravenous antibiotics for three days.","zh-TW":"患者靜脈注射抗生素治療了三天。"},{"en":"An intravenous drip delivers fluids and medication efficiently.","zh-TW":"靜脈滴注有效地輸送液體和藥物。"}]', '{"abbreviation":"IV","adverb":"intravenously"}', NULL, 4, 3674, NULL),
(3675, 'intricate', '/''ɪntrɪkɪt/', 'adjective', '{"zh-TW":["錯綜複雜的；精細的"],"en":["very complicated or detailed; having many small parts or features"]}', NULL, 'intricate design / intricate process / intricate pattern', '[{"en":"The watch''s intricate mechanism had over three hundred individual parts.","zh-TW":"這塊手錶錯綜複雜的機械裝置有超過三百個單獨的零件。"},{"en":"The diplomats worked through the intricate details of the trade agreement.","zh-TW":"外交官們處理了貿易協議的錯綜複雜的細節。"}]', '{"adverb":"intricately","noun":"intricacy"}', NULL, 3, 3675, NULL),
(3676, 'intrinsic', '/''ɪnˌtrɪnsɪk/', 'adjective', '{"zh-TW":["內在的；固有的"],"en":["belonging naturally; essential to the nature of something"]}', NULL, 'intrinsic value / intrinsic motivation / intrinsic quality', '[{"en":"Intrinsic motivation, driven by personal interest, tends to lead to deeper learning.","zh-TW":"由個人興趣驅動的內在動力往往能帶來更深入的學習。"},{"en":"The intrinsic beauty of the landscape drew photographers from around the world.","zh-TW":"這片景觀的內在美吸引了來自世界各地的攝影師。"}]', '{"adverb":"intrinsically"}', NULL, 3, 3676, NULL),
(3677, 'intrinsic value', '/ɪnˈtrɪnsɪk ˈvæljuː/', 'noun', '{"zh-TW":["內在價值"],"en":["the actual or true value of a company or asset based on fundamental analysis"]}', NULL, 'calculate intrinsic value / below intrinsic value / intrinsic value assessment', '[{"en":"The analyst calculated the intrinsic value using a DCF model.","zh-TW":"分析師使用DCF模型計算了內在價值。"},{"en":"Buffett invests when a stock trades well below its intrinsic value.","zh-TW":"巴菲特在股票以遠低於其內在價值的價格交易時投資。"}]', NULL, NULL, 5, 3677, NULL),
(3678, 'introduce', '/ˌɪntrəˈduːs/', 'verb', '{"zh-TW":["介紹；引進"],"en":["to make someone known to another; to bring something new"]}', NULL, 'introduce a product/policy / introduce someone to', '[{"en":"Allow me to introduce our new team member.","zh-TW":"請允許我介紹我們的新團隊成員。"},{"en":"The company introduced a new product line.","zh-TW":"公司推出了新的產品線。"}]', '{"noun":"introduction","verb":"introduce","adjective":"introductory"}', NULL, 3, 3678, 144),
(3679, 'introduction', 'ˌɪntrəˈdʌkʃən', 'noun', '{"zh-TW":["介紹；引言","入門"],"en":["the act of presenting someone","a first section"]}', NULL, 'brief introduction/letter of introduction', '[{"en":"Please give a brief introduction of yourself.","zh-TW":"請簡要介紹自己。"}]', '{"verb":"introduce","adjective":"introductory","adverb":"introductorily"}', NULL, 4, 3679, 586),
(3680, 'introspection', '/''ɪntrəˌspekʃən/', 'noun', '{"zh-TW":["內省；自我反思"],"en":["the examination or observation of one''s own mental and emotional processes"]}', NULL, 'encourage introspection / benefit of introspection / period of introspection', '[{"en":"After the project failure, the manager used introspection to identify her own role in the outcome.","zh-TW":"項目失敗後，管理者進行自我反思，識別出她在結果中的作用。"},{"en":"Meditation is a tool that encourages regular introspection and self-awareness.","zh-TW":"冥想是鼓勵定期內省和自我意識的工具。"}]', '{"verb":"introspect","adjective":"introspective","adverb":"introspectively"}', NULL, 5, 3680, NULL),
(3681, 'introspective', '/''ɪntrəˈspektɪv/', 'adjective', '{"zh-TW":["自省的；沉思的"],"en":["examining or characterized by examination of one''s own mental and emotional processes"]}', NULL, 'introspective person / introspective approach / deeply introspective', '[{"en":"An introspective leader regularly evaluates their own decisions and biases.","zh-TW":"自省的領導者定期評估自己的決策和偏見。"},{"en":"The team''s introspective review led to important lessons for future projects.","zh-TW":"團隊的自省審查為未來的項目提供了重要的教訓。"}]', '{"adverb":"introspectively","noun":"introspection"}', NULL, 5, 3681, NULL),
(3682, 'intuitive', '/ɪnˈtuːɪtɪv/', 'adjective', '{"zh-TW":["直覺的；易懂的"],"en":["easy to understand without instruction; based on intuition"]}', NULL, 'intuitive interface/design/understanding', '[{"en":"The software has an intuitive user interface.","zh-TW":"該軟體有直覺式的使用者介面。"},{"en":"She has an intuitive understanding of customer needs.","zh-TW":"她對客戶需求有直覺性的理解。"}]', '{"noun":"intuition","adjective":"intuitive","adverb":"intuitively"}', NULL, 3, 3682, NULL),
(3683, 'intuitively', '/''ɪnˈtjuːɪtɪvli/', 'adverb', '{"zh-TW":["直觉地；憑直覺地"],"en":["in a way that is based on what one feels to be true without conscious reasoning"]}', NULL, 'understand intuitively / know intuitively / act intuitively', '[{"en":"She intuitively understood what the client wanted before they even articulated it.","zh-TW":"她在客戶表達之前就憑直覺理解了他們的需求。"},{"en":"The user interface was designed to be used intuitively without requiring a manual.","zh-TW":"用戶界面被設計成可以憑直覺使用，無需說明書。"}]', '{"adjective":"intuitive"}', NULL, 4, 3683, NULL),
(3684, 'invaluable', '/ɪnˈvæljuəbl/', 'adjective', '{"zh-TW":["無價的；極有價值的"],"en":["extremely useful; priceless"]}', NULL, 'invaluable experience/resource/asset', '[{"en":"Her expertise has been invaluable to the project.","zh-TW":"她的專業知識對項目極有價值。"},{"en":"The internship provided invaluable work experience.","zh-TW":"實習提供了寶貴的工作經驗。"}]', '{"adjective":"invaluable, valuable"}', NULL, 4, 3684, NULL),
(3685, 'invariant', '/ɪnˈveəriənt/', 'adjective', '{"zh-TW":["不變的；恆量"],"en":["never changing; remaining constant in different situations"]}', NULL, 'invariant rule / invariant principle / invariant property', '[{"en":"The speed of light is an invariant in Einstein''s theory of relativity.","zh-TW":"光速在愛因斯坦相對論中是不變量。"},{"en":"This mathematical property is invariant under rotation.","zh-TW":"這個數學性質在旋轉下是不變的。"}]', '{"noun":"invariance","adverb":"invariantly"}', NULL, 3, 3685, NULL),
(3686, 'invasive species', '/ɪnˈveɪsɪv ˈspiːʃiːz/', 'noun', '{"zh-TW":["入侵物種"],"en":["non-native species that spread and cause damage to ecosystems"]}', NULL, 'control invasive species / invasive species management / spread of invasive species', '[{"en":"Invasive species outcompete native plants and animals for resources.","zh-TW":"入侵物種在資源競爭中超過本土植物和動物。"},{"en":"Early detection is key to preventing invasive species from establishing.","zh-TW":"早期發現是防止入侵物種建立的關鍵。"}]', NULL, NULL, 5, 3686, NULL),
(3687, 'inventory', '/ˈɪnvəntɔːri/', 'noun', '{"zh-TW":["庫存；存貨清單"],"en":["a complete list of items in stock","a complete list of goods in stock"]}', '{"prefix":{"text":"in-","meaning":"in (在內)"},"root":{"text":"vent","meaning":"come (來)"},"logic":"進來的東西的集合，即「庫存」。"}', 'inventory management / take inventory; take inventory / inventory management / carry inventory', '[{"en":"We need to check the inventory before ordering more.","zh-TW":"我們需要在追加訂購前檢查庫存。"},{"en":"The store takes inventory every month.","zh-TW":"這家店每個月盤點一次庫存。"},{"en":"The store needs to take inventory at year-end.","zh-TW":"商店需要在年底盤點庫存。"},{"en":"Good inventory management reduces costs.","zh-TW":"良好的庫存管理可以降低成本。"}]', '{"noun":"inventory"}', NULL, 3, 3687, 377),
(3688, 'inventory control', '/ɪnˈventɔːri kənˈtroʊl/', 'noun', '{"zh-TW":["庫存控制"],"en":["the process of managing stock levels to balance demand and cost"]}', NULL, 'tighten inventory control / inventory control system', '[{"en":"Automated inventory control reduced stockouts by 30%.","zh-TW":"自動化庫存控制將缺貨次數減少了30%。"},{"en":"Poor inventory control leads to excess stock and tied-up capital.","zh-TW":"糟糕的庫存控制導致過剩庫存和佔用的資本。"}]', NULL, NULL, 5, 3688, NULL),
(3689, 'inventory count', '/ɪnˈventɔːri kaʊnt/', 'noun', '{"zh-TW":["庫存盤點"],"en":["a physical count of all items in stock at a given time"]}', NULL, 'conduct an inventory count / annual inventory count', '[{"en":"The warehouse team completed the annual inventory count overnight.","zh-TW":"倉庫團隊連夜完成了年度庫存盤點。"},{"en":"Inventory count discrepancies are investigated immediately.","zh-TW":"庫存盤點差異立即進行調查。"}]', NULL, NULL, 5, 3689, NULL),
(3690, 'inventory management', '/ˈɪnvəntɔːri ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["庫存管理"],"en":["the process of overseeing and controlling stock levels"]}', NULL, 'efficient inventory management / inventory management system', '[{"en":"Effective inventory management reduces waste and stockouts.","zh-TW":"有效的庫存管理減少了浪費和缺貨。"},{"en":"The retail chain uses automated inventory management software.","zh-TW":"這家連鎖零售商使用自動化的庫存管理軟體。"}]', NULL, NULL, 5, 3690, NULL),
(3691, 'inventory management system', '/ˈɪnvəntəri ˈmænɪdʒmənt ˈsɪstəm/', 'noun', '{"zh-TW":["庫存管理系統"],"en":["software that tracks inventory levels, orders, and deliveries in real time"]}', NULL, 'implement an inventory management system / inventory management system features', '[{"en":"The inventory management system automatically triggers replenishment orders.","zh-TW":"庫存管理系統自動觸發補貨訂單。"},{"en":"An inventory management system reduces stockouts and overstock situations.","zh-TW":"庫存管理系統減少了缺貨和庫存過剩的情況。"}]', NULL, NULL, 5, 3691, NULL),
(3692, 'inventory shrinkage', '/ˈɪnvəntɔːri ˈʃrɪŋkɪdʒ/', 'noun', '{"zh-TW":["庫存短缺；盤虧"],"en":["the loss of inventory from theft, damage, or accounting errors"]}', NULL, 'prevent inventory shrinkage / inventory shrinkage rate', '[{"en":"Retail stores implement security measures to reduce inventory shrinkage.","zh-TW":"零售店實施安全措施以減少庫存短缺。"},{"en":"Annual stocktakes reveal the total inventory shrinkage over the year.","zh-TW":"年度盤點揭示了全年的庫存短缺總量。"}]', NULL, NULL, 5, 3692, NULL),
(3693, 'inventory turnover', '/ɪnˈvɛntəri ˈtɜːrnəʊvər/', 'noun', '{"zh-TW":["存貨周轉率"],"en":["the rate at which inventory is sold and replaced"]}', NULL, 'improve inventory turnover / low inventory turnover', '[{"en":"High inventory turnover indicates strong sales performance.","zh-TW":"高存貨周轉率表示銷售表現強勁。"},{"en":"The retailer improved its inventory turnover through better forecasting.","zh-TW":"零售商通過更好的預測改善了存貨周轉率。"}]', NULL, NULL, 5, 3693, NULL),
(3694, 'invest', '/ɪnˈvest/', 'verb', '{"zh-TW":["投資"],"en":["to put money into something for profit","to put money into something to make a profit"]}', '{"prefix":{"text":"in-","meaning":"in (進入)"},"root":{"text":"vest","meaning":"clothe/cover (覆蓋)"},"logic":"把資金包進某事物中，即「投資」。"}', 'invest in / invest time / invest money; invest in stocks/real estate / invest time', '[{"en":"She invested her savings in stocks.","zh-TW":"她把積蓄投資在股票上。"},{"en":"The company invested heavily in research.","zh-TW":"公司在研究方面投入了大量資金。"},{"en":"She invested heavily in technology stocks.","zh-TW":"她大量投資科技股。"},{"en":"The company plans to invest in new equipment.","zh-TW":"公司計劃投資新設備。"}]', '{"noun":"investment","noun2":"investor","verb":"invest"}', NULL, 2, 3694, NULL),
(3695, 'invest in technology', '/ɪnˈvest ɪn tekˈnɒlədʒi/', 'verb', '{"zh-TW":["投資技術"],"en":["to commit funds to improving or acquiring technology systems"]}', NULL, 'invest heavily in technology / invest in new technology', '[{"en":"The company invested heavily in technology to improve service delivery.","zh-TW":"公司在技術方面投入了大量資金以改善服務交付。"},{"en":"Investing in technology can reduce long-term operational costs.","zh-TW":"投資技術可以降低長期運營成本。"}]', NULL, NULL, 5, 3695, NULL),
(3696, 'investigate', '/ɪnˈvestɪɡeɪt/', 'verb', '{"zh-TW":["調查；研究"],"en":["to carry out a systematic examination"]}', NULL, 'investigate a case/claim/complaint', '[{"en":"Police are investigating the cause of the fire.","zh-TW":"警方正在調查火災原因。"},{"en":"The committee will investigate the allegations.","zh-TW":"委員會將調查這些指控。"}]', '{"noun":"investigation, investigator","verb":"investigate","adjective":"investigative"}', NULL, 4, 3696, NULL),
(3697, 'investment', '/ɪnˈvɛstmənt/', 'noun', '{"zh-TW":["投資"],"en":["money put into something to generate profit or income"]}', NULL, 'return on investment / long-term investment', '[{"en":"The company made a significant investment in technology.","zh-TW":"公司在技術方面進行了重大投資。"},{"en":"Diversifying your investment portfolio reduces risk.","zh-TW":"分散投資組合可降低風險。"}]', '{"verb":"invest","noun":"investor","adjective":"invested"}', NULL, 4, 3697, 378),
(3698, 'investment appraisal', '/ɪnˈvestmənt əˈpreɪzəl/', 'noun', '{"zh-TW":["投資評估"],"en":["the process of evaluating the financial viability of a capital investment"]}', NULL, 'conduct an investment appraisal / investment appraisal method', '[{"en":"Net present value is a key method in investment appraisal.","zh-TW":"淨現值是投資評估的關鍵方法。"},{"en":"An investment appraisal was completed before the board approved funding.","zh-TW":"在董事會批准資金前完成了投資評估。"}]', NULL, NULL, 5, 3698, NULL),
(3699, 'investment bank', '/ɪnˈvestmənt bæŋk/', 'noun', '{"zh-TW":["投資銀行"],"en":["a financial institution providing services such as underwriting and corporate advisory"]}', NULL, 'hire an investment bank / investment bank mandate', '[{"en":"The company engaged an investment bank to manage its IPO process.","zh-TW":"公司聘請了投資銀行管理其IPO流程。"},{"en":"Investment banks advise on mergers, acquisitions, and capital raising.","zh-TW":"投資銀行就合併、收購和籌集資本提供建議。"}]', '{"adjective":"investment banking"}', NULL, 5, 3699, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3700, 'investment committee', '/ɪnˈvestmənt kəˈmɪti/', 'noun', '{"zh-TW":["投資委員會"],"en":["a group responsible for overseeing and approving investment decisions"]}', NULL, 'present to the investment committee / investment committee approval', '[{"en":"All major investments require investment committee approval.","zh-TW":"所有重大投資都需要投資委員會批准。"},{"en":"The investment committee met quarterly to review the portfolio.","zh-TW":"投資委員會每季召開會議審查投資組合。"}]', NULL, NULL, 5, 3700, NULL),
(3701, 'investment grade', '/ɪnˈvestmənt ɡreɪd/', 'noun', '{"zh-TW":["投資級別"],"en":["a credit rating indicating low risk of default"]}', NULL, 'investment grade bond / investment grade rating', '[{"en":"The company''s bonds were upgraded to investment grade by Moody''s.","zh-TW":"該公司的債券被穆迪升級為投資級別。"},{"en":"Investment grade bonds offer lower yields but greater security.","zh-TW":"投資級別債券提供較低收益率但更高安全性。"}]', NULL, NULL, 5, 3701, NULL),
(3702, 'investment strategy', '/ɪnˈvestmənt ˈstrætədʒi/', 'noun', '{"zh-TW":["投資策略"],"en":["a plan for allocating funds across different assets or opportunities"]}', NULL, 'develop an investment strategy / review the investment strategy', '[{"en":"The fund''s investment strategy balances growth and income.","zh-TW":"基金的投資策略在增長和收入之間取得平衡。"},{"en":"A long-term investment strategy outperforms short-term trading.","zh-TW":"長期投資策略優於短期交易。"}]', NULL, NULL, 5, 3702, NULL),
(3703, 'inviolable', '/ɪnˈvaɪələbəl/', 'adjective', '{"zh-TW":["不可侵犯的；神聖不可侵犯的"],"en":["never to be broken or changed; too sacred to be interfered with"]}', NULL, 'inviolable right / inviolable principle / inviolable rule', '[{"en":"Freedom of speech is considered an inviolable right in democratic societies.","zh-TW":"言論自由在民主社會中被視為不可侵犯的權利。"},{"en":"The treaty established inviolable borders between the two countries.","zh-TW":"條約確立了兩國之間不可侵犯的邊界。"}]', '{"adverb":"inviolably","noun":"inviolability"}', NULL, 4, 3703, NULL),
(3704, 'invitation', 'ˌɪnvɪˈteɪʃən', 'noun', '{"zh-TW":["邀請；請帖","邀請函"],"en":["a written or spoken request","a card asking someone to attend"]}', NULL, 'formal invitation/send an invitation', '[{"en":"We sent invitations to all stakeholders.","zh-TW":"我們向所有利益相關者發送了邀請。"}]', '{"verb":"invite","adjective":"inviting","adverb":"invitingly"}', NULL, 4, 3704, 379),
(3705, 'invite', 'ɪnˈvaɪt', 'verb', '{"zh-TW":["邀請；招待","引起"],"en":["to ask someone to attend","to cause something to happen"]}', NULL, 'invite to a meeting/event', '[{"en":"We would like to invite you to our launch event.","zh-TW":"我們想邀請您參加我們的發布活動。"}]', '{"noun":"invitation","adjective":"inviting","adverb":"invitingly"}', NULL, 2, 3705, NULL),
(3706, 'invoice', '/ˈɪnvɔɪs/', 'noun, verb', '{"zh-TW":["發票；帳單","開發票"],"en":["a bill for goods or services","to send an invoice"]}', NULL, 'issue/send an invoice / pay an invoice', '[{"en":"Please send the invoice to our accounting department.","zh-TW":"請將發票發送到我們的會計部門。"},{"en":"We will invoice you at the end of the month.","zh-TW":"我們會在月底向您開具發票。"}]', '{"noun":"invoice","verb":"invoke"}', NULL, 3, 3706, 145),
(3707, 'invoice approval', '/ˈɪnvɔɪs əˈpruːvəl/', 'noun', '{"zh-TW":["發票審批"],"en":["the authorization process for verifying and approving invoices before payment"]}', NULL, 'implement invoice approval / invoice approval workflow', '[{"en":"A three-way match is used in invoice approval to verify accuracy.","zh-TW":"發票審批中使用三方匹配來驗證準確性。"},{"en":"Streamlining the invoice approval process reduces payment delays.","zh-TW":"簡化發票審批流程減少了付款延誤。"}]', NULL, NULL, 5, 3707, NULL),
(3708, 'invoice discounting', '/ˈɪnvɔɪs ˈdɪskaʊntɪŋ/', 'noun', '{"zh-TW":["發票貼現"],"en":["borrowing money against unpaid invoices while retaining credit control"]}', NULL, 'use invoice discounting / invoice discounting facility', '[{"en":"Invoice discounting improved the firm''s short-term liquidity.","zh-TW":"發票貼現改善了公司的短期流動性。"},{"en":"The bank offered invoice discounting at a rate of 1.5%.","zh-TW":"銀行以1.5%的利率提供發票貼現服務。"}]', NULL, NULL, 5, 3708, NULL),
(3709, 'invoice factoring', '/ˈɪnvɔɪs ˈfæktərɪŋ/', 'noun', '{"zh-TW":["發票保理"],"en":["selling outstanding invoices to a third party at a discount for immediate cash"]}', NULL, 'use invoice factoring / invoice factoring facility', '[{"en":"Invoice factoring provided the startup with immediate working capital.","zh-TW":"發票保理為新創公司提供了即時營運資金。"},{"en":"Invoice factoring is a fast way to improve short-term cash flow.","zh-TW":"發票保理是改善短期現金流的快速方法。"}]', NULL, NULL, 5, 3709, NULL),
(3710, 'invoice financing', '/ˈɪnvɔɪs ˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["發票融資"],"en":["using unpaid invoices as collateral to obtain short-term funding"]}', NULL, 'use invoice financing / invoice financing facility', '[{"en":"Invoice financing provided liquidity while waiting for customer payments.","zh-TW":"在等待客戶付款期間，發票融資提供了流動性。"},{"en":"Invoice financing is particularly useful for businesses with long payment cycles.","zh-TW":"對於付款週期長的企業來說，發票融資特別有用。"}]', NULL, NULL, 5, 3710, NULL),
(3711, 'invoice processing', '/ˈɪnvɔɪs ˈprəʊsɛsɪŋ/', 'noun', '{"zh-TW":["發票處理"],"en":["the workflow for receiving, verifying, and paying invoices"]}', NULL, 'automate invoice processing / invoice processing system', '[{"en":"The company automated invoice processing to reduce errors.","zh-TW":"公司自動化了發票處理以減少錯誤。"},{"en":"Efficient invoice processing ensures timely payments.","zh-TW":"高效的發票處理確保了及時付款。"}]', NULL, NULL, 5, 3711, NULL),
(3712, 'invoice reconciliation', '/ˈɪnvɔɪs ˌrekənsɪliˈeɪʃən/', 'noun', '{"zh-TW":["發票核對；發票對帳"],"en":["matching invoices to purchase orders and receipts for verification"]}', NULL, 'perform invoice reconciliation / invoice reconciliation process', '[{"en":"Invoice reconciliation prevents duplicate or incorrect payments.","zh-TW":"發票核對防止了重複或錯誤付款。"},{"en":"The accounts team performs invoice reconciliation weekly.","zh-TW":"帳務團隊每週進行發票核對。"}]', NULL, NULL, 5, 3712, NULL),
(3713, 'involve', '/ɪnˈvɑːlv/', 'verb', '{"zh-TW":["涉及；包含；使參與"],"en":["to include as a necessary part; to cause someone to participate"]}', NULL, 'involve someone in / be involved in', '[{"en":"The project involves a team of 20 people.","zh-TW":"該項目涉及一個20人的團隊。"},{"en":"She was deeply involved in the planning process.","zh-TW":"她深入參與了規劃過程。"}]', '{"noun":"involvement","verb":"involve","adjective":"involved"}', NULL, 3, 3713, 146),
(3714, 'IPO', '/ˌaɪ piː ˈoʊ/', 'noun', '{"zh-TW":["首次公開募股"],"en":["initial public offering; first sale of company shares to the public"]}', NULL, 'launch an IPO / IPO price / IPO prospectus / pre-IPO', '[{"en":"The company raised $500 million through its IPO.","zh-TW":"公司通過首次公開募股籌集了5億美元。"},{"en":"Investors were eager to buy shares in the highly anticipated IPO.","zh-TW":"投資者急於購買備受期待的首次公開募股的股票。"}]', '{"full form":"initial public offering"}', NULL, 1, 3714, NULL),
(3715, 'irrefutable', '/''ɪrɪˌfjuːtəbəl/', 'adjective', '{"zh-TW":["無可辯駁的；確鑿的"],"en":["impossible to deny or disprove; certain and undeniable"]}', NULL, 'irrefutable evidence / irrefutable argument / irrefutable proof', '[{"en":"The prosecution presented irrefutable evidence that linked the defendant to the crime.","zh-TW":"檢察官提供了將被告與犯罪聯繫起來的無可辯駁的證據。"},{"en":"Her research produced irrefutable proof that the new treatment was effective.","zh-TW":"她的研究提供了確鑿的證明，表明新療法是有效的。"}]', '{"adverb":"irrefutably"}', NULL, 4, 3715, NULL),
(3716, 'island', '/ˈaɪlənd/', 'noun', '{"zh-TW":["島嶼"],"en":["a piece of land surrounded by water"]}', NULL, 'island resort / remote island', '[{"en":"The conference is at an island resort.","zh-TW":"會議在一個島嶼度假村舉行。"},{"en":"We source materials from the island.","zh-TW":"我們從島上採購原料。"}]', '{"noun":"island","noun2":"islander"}', NULL, 2, 3716, NULL),
(3717, 'isolate', '/ˈaɪsəleɪt/', 'verb', '{"zh-TW":["隔離；孤立"],"en":["to separate from others"]}', NULL, 'isolate a problem/variable / socially isolated', '[{"en":"Scientists isolated the virus in the laboratory.","zh-TW":"科學家在實驗室中分離了病毒。"},{"en":"The town was isolated by the flood.","zh-TW":"小鎮因洪水而被孤立。"}]', '{"noun":"isolation","verb":"isolate","adjective":"isolated"}', NULL, 3, 3717, NULL),
(3718, 'issuance', '/ˈɪʃuəns/', 'noun', '{"zh-TW":["發行；發行量"],"en":["the process of officially producing and distributing something, especially securities"]}', NULL, 'bond issuance / debt issuance / share issuance', '[{"en":"The bond issuance was oversubscribed three times due to strong investor demand.","zh-TW":"由於強勁的投資者需求，債券發行被超額認購三倍。"},{"en":"New share issuance dilutes the ownership stake of existing shareholders.","zh-TW":"新股發行稀釋了現有股東的所有權比例。"}]', '{"verb":"issue"}', NULL, 3, 3718, NULL),
(3719, 'issue', '/ˈɪʃuː/', 'noun, verb', '{"zh-TW":["議題；問題","發行；發布"],"en":["a topic for discussion; a problem","to officially provide or publish"]}', NULL, 'address an issue / issue a statement/warning', '[{"en":"We need to address this issue immediately.","zh-TW":"我們需要立即解決這個問題。"},{"en":"The company issued a press release.","zh-TW":"公司發布了一份新聞稿。"}]', '{"noun":"issue","verb":"issue"}', NULL, 2, 3719, 147),
(3720, 'issue log', '/ˈɪʃuː lɒɡ/', 'noun', '{"zh-TW":["問題記錄冊"],"en":["a document tracking open issues, their status, and assigned owners"]}', NULL, 'maintain an issue log / update the issue log / review the issue log', '[{"en":"The project manager maintained an issue log throughout the build phase.","zh-TW":"項目經理在整個建設階段維護問題記錄冊。"},{"en":"All open issues in the log must be resolved before go-live.","zh-TW":"記錄冊中的所有未解決問題必須在上線前解決。"}]', NULL, NULL, 3, 3720, NULL),
(3721, 'issue price', '/ˈɪʃuː praɪs/', 'noun', '{"zh-TW":["發行價格"],"en":["the price at which a new security is offered to investors when first issued"]}', NULL, 'set the issue price / issue price discount', '[{"en":"The bond''s issue price was 98% of face value, reflecting a 2% discount.","zh-TW":"債券的發行價格為面值的98%，反映了2%的折扣。"},{"en":"A high issue price signals strong investor demand for the new shares.","zh-TW":"高發行價格表明投資者對新股的強勁需求。"}]', NULL, NULL, 4, 3721, NULL),
(3722, 'issued capital', '/ˈɪʃuːd ˈkæpɪtəl/', 'noun', '{"zh-TW":["已發行資本"],"en":["the portion of authorized share capital that has been issued to shareholders"]}', NULL, 'report issued capital / increase issued capital', '[{"en":"The company increased its issued capital through a rights issue.","zh-TW":"公司通過供股增加了已發行資本。"},{"en":"Issued capital appears in the equity section of the balance sheet.","zh-TW":"已發行資本出現在資產負債表的股東權益部分。"}]', NULL, NULL, 5, 3722, NULL),
(3723, 'issuer', '/ˈɪʃuːər/', 'noun', '{"zh-TW":["發行方；發行人"],"en":["an entity that creates and offers financial instruments for sale"]}', NULL, 'bond issuer / securities issuer / identify the issuer', '[{"en":"The issuer is responsible for the accuracy of the prospectus.","zh-TW":"發行方對招股書的準確性負責。"},{"en":"A reputable issuer lowers investor risk in the primary market.","zh-TW":"知名的發行方降低了一級市場投資者的風險。"}]', '{"verb":"issue","adjective":"issued"}', NULL, 2, 3723, NULL),
(3724, 'IT support', '/aɪ tiː səˈpɔːrt/', 'noun', '{"zh-TW":["資訊技術支援"],"en":["assistance with computers and technology systems"]}', NULL, 'contact IT support / IT support team', '[{"en":"Contact IT support if you experience login issues.","zh-TW":"如果遇到登入問題，請聯繫資訊技術支援。"},{"en":"The IT support team responded to the outage within minutes.","zh-TW":"資訊技術支援團隊在幾分鐘內回應了系統中斷。"}]', NULL, NULL, 4, 3724, NULL),
(3725, 'item', '/ˈaɪtəm/', 'noun', '{"zh-TW":["項目；物品"],"en":["an individual thing or unit","a single thing in a list or group"]}', '{"root":{"text":"item","meaning":"also (同樣地)"},"logic":"源自拉丁語 item（同樣地），用於列舉清單中的各項。"}', 'item number / luxury item; agenda item / item on the list', '[{"en":"Each item is clearly labeled with a price.","zh-TW":"每件商品都清楚標示價格。"},{"en":"This is a popular item among young customers.","zh-TW":"這是年輕顧客中的熱門商品。"},{"en":"The first item on the agenda is the budget.","zh-TW":"議程上的第一項是預算。"},{"en":"All items must be checked before shipping.","zh-TW":"所有物品在出貨前必須檢查。"}]', '{"verb":"itemize","noun":"item"}', NULL, 1, 3725, NULL),
(3726, 'iteration', '/ˌɪtəˈreɪʃən/', 'noun', '{"zh-TW":["迭代"],"en":["a repeated cycle of development in which improvements are made each time"]}', NULL, 'agile iteration / product iteration / rapid iteration', '[{"en":"Each iteration delivers a working increment of the product.","zh-TW":"每次迭代交付產品的一個可工作的增量。"},{"en":"Rapid iteration allows the team to respond quickly to feedback.","zh-TW":"快速迭代使團隊能夠快速響應反饋。"}]', '{"verb":"iterate","adjective":"iterative"}', NULL, 3, 3726, NULL),
(3727, 'iterative', '/ˈɪtərətɪv/', 'adjective', '{"zh-TW":["反覆的；迭代的"],"en":["relating to a process of repetition to achieve a desired result"]}', NULL, 'iterative process / iterative design / iterative approach', '[{"en":"Software development typically follows an iterative cycle.","zh-TW":"軟體開發通常遵循迭代循環。"},{"en":"Iterative feedback improves the quality of academic writing.","zh-TW":"反覆的反饋可以提高學術寫作的品質。"}]', '{"noun":"iteration","verb":"iterate"}', NULL, 3, 3727, NULL),
(3728, 'iterative process', '/ˈɪtərətɪv ˈprəʊses/', 'noun', '{"zh-TW":["反覆迭代的過程"],"en":["a process repeated to approach a desired result"]}', NULL, 'follow an iterative process / iterative process of design / iterative refinement process', '[{"en":"Policy development is an iterative process of testing and learning.","zh-TW":"政策制定是一個測試和學習的反覆迭代過程。"},{"en":"An iterative process of prototyping and testing accelerates product development.","zh-TW":"原型設計和測試的反覆迭代過程加速了產品開發。"}]', NULL, NULL, 5, 3728, NULL),
(3729, 'itinerary', '/aɪˈtɪnəreri/', 'noun', '{"zh-TW":["行程；旅程"],"en":["a planned route or schedule of travel"]}', NULL, 'travel itinerary / detailed itinerary', '[{"en":"Please send me the detailed itinerary for the trip.","zh-TW":"請把旅行的詳細行程發給我。"},{"en":"The itinerary includes visits to three cities.","zh-TW":"行程包括參觀三個城市。"}]', '{"noun":"itinerary"}', NULL, 3, 3729, NULL),
(3730, 'itinerary planning', '/''aɪˌtɪnərəri ˌplænɪŋ/', 'noun', '{"zh-TW":["行程規劃；旅遊計劃"],"en":["the process of planning a detailed schedule for a trip"]}', NULL, 'do itinerary planning / careful itinerary planning / itinerary planning tips', '[{"en":"Good itinerary planning allows you to make the most of your time at each destination.","zh-TW":"好的行程規劃讓你能充分利用在每個目的地的時間。"},{"en":"She spent two weeks on itinerary planning before her three-week European trip.","zh-TW":"她在三週歐洲旅行之前花了兩週時間規劃行程。"}]', NULL, NULL, 5, 3730, NULL),
(3731, 'jargon', '/ˈdʒɑːrɡən/', 'noun', '{"zh-TW":["行話；專業術語"],"en":["specialized language used by a particular profession"]}', NULL, 'technical/legal/business jargon', '[{"en":"Please avoid using technical jargon in the report.","zh-TW":"請避免在報告中使用技術行話。"},{"en":"The contract is full of legal jargon.","zh-TW":"合同中充滿了法律術語。"}]', '{"noun":"jargon"}', NULL, 2, 3731, NULL),
(3732, 'jealous', '/ˈdʒeləs/', 'adjective', '{"zh-TW":["嫉妒的"],"en":["feeling resentment toward someone because of their advantages"]}', '{"root":{"text":"zeal","meaning":"zeal/fervor (熱情)"},"suffix":{"text":"-ous","meaning":"full of (充滿)"},"logic":"充滿強烈情感（嫉妒）的。"}', 'jealous of / feel jealous', '[{"en":"She was jealous of her sister''s success.","zh-TW":"她嫉妒姐姐的成功。"},{"en":"Don''t be jealous of other people.","zh-TW":"不要嫉妒他人。"}]', '{"noun":"jealousy"}', NULL, 3, 3732, NULL),
(3733, 'jeopardize', '/ˈdʒepərdaɪz/', 'verb', '{"zh-TW":["危及；損害"],"en":["to put something in danger of being harmed or lost"]}', NULL, 'jeopardize safety/chances/career', '[{"en":"His reckless behavior could jeopardize the entire project.","zh-TW":"他魯莽的行為可能危及整個項目。"},{"en":"Don''t jeopardize your career over a minor disagreement.","zh-TW":"不要因為小分歧而危及你的職業生涯。"}]', '{"noun":"jeopardy","verb":"jeopardize"}', NULL, 4, 3733, NULL),
(3734, 'jet bridge', '/dʒɛt brɪdʒ/', 'noun', '{"zh-TW":["空橋；登機橋"],"en":["a movable tunnel connecting the terminal to an aircraft"]}', NULL, 'board via jet bridge / jet bridge access', '[{"en":"Passengers boarded the plane via the jet bridge.","zh-TW":"乘客透過登機橋登上飛機。"},{"en":"Small regional airports may lack jet bridges.","zh-TW":"小型地區機場可能沒有登機橋。"}]', NULL, NULL, 4, 3734, NULL),
(3735, 'jet lag', '/ˈdʒɛt læɡ/', 'noun', '{"zh-TW":["時差反應"],"en":["fatigue felt after crossing time zones"]}', NULL, 'suffer from jet lag / recover from jet lag', '[{"en":"She suffered from jet lag after the long flight.","zh-TW":"長途飛行後她出現了時差反應。"},{"en":"Drinking plenty of water can help reduce jet lag.","zh-TW":"多喝水有助於減輕時差反應。"}]', '{"adjective":"jet-lagged"}', NULL, 3, 3735, NULL),
(3736, 'job', '/dʒɑːb/', 'noun', '{"zh-TW":["工作；職位"],"en":["a paid position of employment"]}', NULL, 'job opening / job description / full-time job', '[{"en":"She applied for a job at the marketing firm.","zh-TW":"她向那家行銷公司申請了一份工作。"},{"en":"The company posted a new job opening online.","zh-TW":"公司在網上發布了一個新職位。"}]', '{"noun":"job","adjective":"jobless"}', NULL, 1, 3736, NULL),
(3737, 'job costing', '/dʒɒb ˈkɒstɪŋ/', 'noun', '{"zh-TW":["工作成本核算"],"en":["a method of tracking costs for each individual job or project separately"]}', NULL, 'apply job costing / job costing system', '[{"en":"Job costing allowed the firm to identify which projects were most profitable.","zh-TW":"工作成本核算使公司能夠識別哪些項目最盈利。"},{"en":"Construction companies rely on job costing to manage project budgets.","zh-TW":"建築公司依賴工作成本核算來管理項目預算。"}]', NULL, NULL, 4, 3737, NULL),
(3738, 'job description', '/dʒɒb dɪˈskrɪpʃən/', 'noun', '{"zh-TW":["職位描述"],"en":["a document detailing the duties, responsibilities, and requirements of a job"]}', NULL, 'write a job description / update the job description / job description template', '[{"en":"The job description listed the required skills and experience.","zh-TW":"職位描述列出了所需的技能和經驗。"},{"en":"A clear job description helps attract the right candidates.","zh-TW":"清晰的職位描述有助於吸引合適的候選人。"}]', '{"abbreviation":"JD"}', NULL, 5, 3738, NULL),
(3739, 'job evaluation', '/dʒɒb ɪˌvæljuˈeɪʃən/', 'noun', '{"zh-TW":["職位評估"],"en":["a systematic process for assessing the relative worth of jobs within an organization"]}', NULL, 'conduct job evaluation / job evaluation framework', '[{"en":"Job evaluation helps ensure fair and consistent pay structures.","zh-TW":"職位評估有助於確保公平一致的薪酬結構。"},{"en":"A job evaluation led to a redesign of the salary banding system.","zh-TW":"職位評估導致了薪資區間系統的重新設計。"}]', NULL, NULL, 5, 3739, NULL),
(3740, 'job performance', '/dʒɒb pəˈfɔːrməns/', 'noun', '{"zh-TW":["工作績效"],"en":["how well an employee carries out the duties of their role"]}', NULL, 'evaluate job performance / improve job performance', '[{"en":"Regular feedback improves job performance over time.","zh-TW":"定期反饋隨時間推移改善了工作績效。"},{"en":"Job performance is reviewed annually as part of the appraisal process.","zh-TW":"工作績效作為評估流程的一部分每年審查一次。"}]', NULL, NULL, 5, 3740, NULL),
(3741, 'job posting', '/dʒɒb ˈpoʊstɪŋ/', 'noun', '{"zh-TW":["職位公告；招聘廣告"],"en":["an advertisement for a job vacancy published by an employer"]}', NULL, 'publish a job posting / respond to a job posting / internal job posting', '[{"en":"The job posting attracted over 300 applications within a week.","zh-TW":"職位公告在一週內吸引了300多份申請。"},{"en":"Internal job postings encourage employees to grow within the company.","zh-TW":"內部職位公告鼓勵員工在公司內部成長。"}]', '{"plural":"job postings","verb":"post a job"}', NULL, 4, 3741, NULL),
(3742, 'job specification', '/dʒɒb ˌspesɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["職位規格；崗位說明"],"en":["a detailed description of the qualifications and attributes required for a role"]}', NULL, 'write a job specification / match the job specification', '[{"en":"The job specification listed five years of experience as a minimum.","zh-TW":"職位規格將五年工作經驗列為最低要求。"},{"en":"Candidates who do not meet the job specification will not be shortlisted.","zh-TW":"不符合職位規格的候選人將不會進入短名單。"}]', NULL, NULL, 5, 3742, NULL),
(3743, 'job vacancy', '/dʒɒb ˈveɪkənsi/', 'noun', '{"zh-TW":["職位空缺"],"en":["an available position in an organization"]}', NULL, 'post a job vacancy / fill a job vacancy', '[{"en":"The company posted ten job vacancies on its website.","zh-TW":"公司在其網站上發布了十個職位空缺。"},{"en":"Qualified candidates should apply for the job vacancy immediately.","zh-TW":"合格的候選人應立即申請職位空缺。"}]', NULL, NULL, 4, 3743, NULL),
(3744, 'join', '/dʒɔɪn/', 'verb', '{"zh-TW":["加入；連接"],"en":["to become a member of; to connect"]}', NULL, 'join a company/team/organization', '[{"en":"He joined the company in 2019.","zh-TW":"他於2019年加入公司。"},{"en":"Would you like to join us for lunch?","zh-TW":"你想和我們一起吃午飯嗎？"}]', '{"noun":"joint","verb":"join","adjective":"joint"}', NULL, 1, 3744, NULL),
(3745, 'joint', '/dʒɔɪnt/', 'adjective, noun', '{"zh-TW":["共同的；聯合的","關節；接合處"],"en":["shared by two or more parties","a point of connection"]}', NULL, 'joint venture / joint effort / joint account', '[{"en":"The two companies formed a joint venture.","zh-TW":"兩家公司成立了一家合資企業。"},{"en":"This was a joint effort between departments.","zh-TW":"這是各部門的共同努力。"}]', '{"noun":"joint","adjective":"joint","adverb":"jointly"}', NULL, 2, 3745, NULL),
(3746, 'joint and several liability', '/dʒɔɪnt ænd ˈsevərəl ˌlaɪəˈbɪlɪti/', 'noun', '{"zh-TW":["連帶及各自責任"],"en":["legal responsibility shared among multiple parties each liable for the full amount"]}', NULL, 'establish joint and several liability / joint and several liability clause', '[{"en":"Under joint and several liability, any defendant can be sued for the full loss.","zh-TW":"在連帶及各自責任下，任何被告都可以被起訴承擔全部損失。"},{"en":"Lenders prefer joint and several liability to reduce default risk.","zh-TW":"貸款機構更喜歡連帶及各自責任以降低違約風險。"}]', NULL, NULL, 5, 3746, NULL),
(3747, 'joint liability', '/dʒɔɪnt laɪˈæbɪlɪti/', 'noun', '{"zh-TW":["連帶責任"],"en":["shared legal responsibility between two or more parties for an obligation"]}', NULL, 'joint and several liability / joint liability agreement', '[{"en":"All partners share joint liability for the firm''s debts.","zh-TW":"所有合夥人共同對公司的債務承擔連帶責任。"},{"en":"Joint liability ensures creditors can pursue any one of the parties.","zh-TW":"連帶責任確保債權人可以追究任何一方的責任。"}]', NULL, NULL, 5, 3747, NULL),
(3748, 'joint stock company', '/dʒɔɪnt stɒk ˈkʌmpəni/', 'noun', '{"zh-TW":["股份公司"],"en":["a company owned by shareholders who hold shares of stock"]}', NULL, 'incorporate a joint stock company / manage a joint stock company', '[{"en":"A joint stock company issues shares to raise capital from investors.","zh-TW":"股份公司通過發行股票向投資者籌集資金。"},{"en":"The largest joint stock companies are listed on stock exchanges.","zh-TW":"最大的股份公司在股票交易所上市。"}]', NULL, NULL, 5, 3748, NULL),
(3749, 'joint tenancy', '/dʒɔɪnt ˈtenənsi/', 'noun', '{"zh-TW":["聯合租賃；共有產權"],"en":["co-ownership of property where all owners have equal, undivided interests"]}', NULL, 'hold property under joint tenancy / joint tenancy agreement', '[{"en":"Under joint tenancy, the surviving owner automatically inherits the other''s share.","zh-TW":"在聯合租賃下，在世的所有者自動繼承另一方的份額。"},{"en":"Joint tenancy is common for married couples purchasing residential property.","zh-TW":"聯合租賃對購買住宅房產的已婚夫婦很常見。"}]', '{"opposite":"tenancy in common"}', NULL, 5, 3749, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3750, 'joint venture', '/ˌdʒɔɪnt ˈventʃər/', 'noun', '{"zh-TW":["合資企業；聯合創業"],"en":["a business arrangement where two parties share ownership"]}', NULL, 'form a joint venture / joint venture partner / joint venture agreement', '[{"en":"The two firms formed a joint venture to enter China.","zh-TW":"兩家公司成立合資企業進入中國市場。"},{"en":"Profits from the joint venture will be split equally.","zh-TW":"合資企業的利潤將平均分配。"}]', '{"adjective":"joint"}', NULL, 5, 3750, NULL),
(3751, 'joint venture agreement', '/dʒɔɪnt ˈventʃər əˈɡriːmənt/', 'noun', '{"zh-TW":["合資協議；合資企業協議"],"en":["a contract establishing the terms of a jointly owned business venture"]}', NULL, 'sign a joint venture agreement / negotiate a joint venture agreement', '[{"en":"Both companies signed a joint venture agreement to share costs.","zh-TW":"兩家公司簽署了合資協議以分擔成本。"},{"en":"The joint venture agreement defines each party contribution and profit split.","zh-TW":"合資協議定義了各方的出資和利潤分配。"}]', NULL, NULL, 5, 3751, NULL),
(3752, 'journal', '/ˈdʒɜːrnl/', 'noun', '{"zh-TW":["期刊；日誌"],"en":["a scholarly publication; a daily record"]}', NULL, 'academic journal / keep a journal', '[{"en":"The research was published in a leading journal.","zh-TW":"該研究發表在一份頂尖期刊上。"},{"en":"She keeps a journal of her daily activities.","zh-TW":"她記錄每天活動的日誌。"}]', '{"noun":"journal, journalism, journalist"}', NULL, 3, 3752, NULL),
(3753, 'journal entry', '/ˈdʒɜːrnəl ˈentri/', 'noun', '{"zh-TW":["分錄；會計分錄"],"en":["a record of a financial transaction in the accounting system"]}', NULL, 'post a journal entry / adjusting journal entry / journal entry format', '[{"en":"The accountant posted a journal entry to record the accrued expense.","zh-TW":"會計師過帳了一筆記錄應計費用的分錄。"},{"en":"Year-end adjusting journal entries ensure accurate financial statements.","zh-TW":"年末調整分錄確保財務報表的準確性。"}]', '{"plural":"journal entries"}', NULL, 5, 3753, NULL),
(3754, 'journalism ethics', '/ˈdʒɜːrnəlɪzəm ˈeθɪks/', 'noun', '{"zh-TW":["新聞倫理"],"en":["the principles and standards that guide journalists'' professional conduct"]}', NULL, 'uphold journalism ethics / journalism ethics code / violate journalism ethics', '[{"en":"Journalism ethics require reporters to verify facts before publication.","zh-TW":"新聞倫理要求記者在發表前核實事實。"},{"en":"The newsroom discussed journalism ethics when deciding whether to publish the story.","zh-TW":"新聞室在決定是否刊登故事時討論了新聞倫理。"}]', NULL, NULL, 5, 3754, NULL),
(3755, 'journey', 'ˈdʒɜːrni', 'noun', '{"zh-TW":["旅程；旅途","歷程"],"en":["travel from one place to another","a process or experience"]}', NULL, 'business journey/long journey', '[{"en":"The business journey has been challenging.","zh-TW":"商業旅程充滿挑戰。"}]', '{"verb":"journey","adjective":"journeying"}', NULL, 3, 3755, NULL),
(3756, 'judge', '/dʒʌdʒ/', 'noun', '{"zh-TW":["法官；裁判","判斷；評價"],"en":["a person who decides cases in court","to form an opinion about"]}', NULL, 'judge a case / pass judgment; judge by/from / pass judgment', '[{"en":"The judge sentenced him to five years.","zh-TW":"法官判他五年。"},{"en":"Don''t judge people by appearances.","zh-TW":"不要以貌取人。"},{"en":"Don''t judge a book by its cover.","zh-TW":"不要以貌取人。"},{"en":"The judge ruled in favor of the plaintiff.","zh-TW":"法官判原告勝訴。"}]', '{"verb":"judge","noun2":"judgment","noun":"judge, judgment","adjective":"judgmental"}', NULL, 2, 3756, NULL),
(3757, 'judgment', '/ˈdʒʌdʒmənt/', 'noun', '{"zh-TW":["判斷力；判決"],"en":["the ability to make sensible decisions; a court decision"]}', NULL, 'good/poor judgment / exercise judgment', '[{"en":"She showed good judgment in handling the situation.","zh-TW":"她在處理情況時表現出良好的判斷力。"},{"en":"The court will deliver its judgment next week.","zh-TW":"法院將在下週做出判決。"}]', '{"noun":"judgment, judge","verb":"judge","adjective":"judgmental"}', NULL, 3, 3757, NULL),
(3758, 'judiciously', '/''dʒuːˈdɪʃəsli/', 'adverb', '{"zh-TW":["明智地；審慎地"],"en":["in a way that shows good judgement; sensibly and carefully"]}', NULL, 'use judiciously / allocate judiciously / invest judiciously', '[{"en":"Resources must be allocated judiciously to maximize the return on investment.","zh-TW":"必須明智地分配資源以最大化投資回報。"},{"en":"She judiciously chose not to comment on the controversial topic in public.","zh-TW":"她明智地選擇不在公開場合對有爭議的話題置評。"}]', '{"adjective":"judicious"}', NULL, 4, 3758, NULL),
(3759, 'jump', '/dʒʌmp/', 'verb', '{"zh-TW":["跳躍；暴漲"],"en":["to push oneself into the air","to increase suddenly"]}', NULL, 'jump start / price jump', '[{"en":"Stock prices jumped 10% today.","zh-TW":"股價今天暴漲了10%。"},{"en":"We need to jump-start the project.","zh-TW":"我們需要快速啟動這個專案。"}]', '{"verb":"jump","noun":"jump"}', NULL, 1, 3759, NULL),
(3760, 'junior suite', '/ˈdʒuːniər swiːt/', 'noun', '{"zh-TW":["小型套房"],"en":["a hotel room that is a step up from a standard room"]}', NULL, 'book a junior suite / junior suite amenities', '[{"en":"The junior suite includes a separate sitting area.","zh-TW":"小型套房包含獨立的休息區域。"},{"en":"We chose a junior suite for a more comfortable stay.","zh-TW":"我們選擇了小型套房以享受更舒適的住宿。"}]', NULL, NULL, 4, 3760, NULL),
(3761, 'jurisdiction', '/ˌdʒʊrɪsˈdɪkʃn/', 'noun', '{"zh-TW":["管轄權；司法權"],"en":["the official power to make legal decisions"]}', NULL, 'fall under/within jurisdiction', '[{"en":"This case falls outside our jurisdiction.","zh-TW":"這個案件不在我們的管轄範圍內。"},{"en":"The dispute was settled by the local jurisdiction.","zh-TW":"爭議由當地司法機關解決。"}]', '{"noun":"jurisdiction","adjective":"jurisdictional"}', NULL, 4, 3761, 797),
(3762, 'jurisprudence', '/ˌdʒʊərɪsˈpruːdəns/', 'noun', '{"zh-TW":["法學；法理學"],"en":["the study or theory of law; a body of legal decisions"]}', NULL, 'legal jurisprudence / constitutional jurisprudence / principles of jurisprudence', '[{"en":"Constitutional jurisprudence interprets the meaning of fundamental laws.","zh-TW":"憲法法理學解釋基本法律的含義。"},{"en":"The ruling established important jurisprudence on privacy rights in the digital age.","zh-TW":"該裁決確立了數字時代隱私權的重要法理學原則。"}]', '{"adjective":"jurisprudential"}', NULL, 5, 3762, NULL),
(3763, 'jury', '/ˈdʒʊri/', 'noun', '{"zh-TW":["陪審團"],"en":["a group of people who decide if someone is guilty"]}', NULL, 'jury duty / jury trial', '[{"en":"The jury found him guilty.","zh-TW":"陪審團裁定他有罪。"},{"en":"She was called for jury duty.","zh-TW":"她被叫去擔任陪審員。"}]', '{"noun2":"juror"}', NULL, 1, 3763, NULL),
(3764, 'just', '/dʒʌst/', 'adjective, adverb', '{"zh-TW":["【主要意義-副詞】只是；剛剛；僅僅","【次要意義-形容詞】公正的；正直的；合理的","【次要意義-副詞】恰好地；正好地"],"en":["[primary - adverb] only; recently; barely","[secondary - adjective] based on fairness and moral rightness","[secondary - adverb] exactly or precisely"]}', NULL, 'just cause / a just decision / just in time / just about / justice', '[{"en":"The committee ensured that all employees received a just and fair evaluation.","zh-TW":"委員會確保所有員工都得到公正且公平的評估。"},{"en":"The new inventory system arrived just in time to prevent a supply shortage.","zh-TW":"新庫存系統恰好及時到達，防止了供應短缺。"},{"en":"His decision to dismiss the employee was considered just under the circumstances.","zh-TW":"在這種情況下，他解雇員工的決定被認為是合理的。"}]', '{"noun":"justice, justification","adverb":"justly"}', '形容詞 just = 「公正的/合理的」（a just cause = 正當理由）是高階用法；just in time（恰好及時/準時制）是製造業和物流業的 TOEIC 必考詞彙。', 1, 3764, NULL),
(3765, 'just cause', '/dʒʌst kɔːz/', 'noun', '{"zh-TW":["正當理由；充分原因"],"en":["a sufficient legal reason to take action such as terminating an employee"]}', NULL, 'dismiss for just cause / prove just cause', '[{"en":"An employee may be dismissed without notice only if there is just cause.","zh-TW":"只有在有正當理由的情況下，才可在不另行通知的情況下解雇員工。"},{"en":"The company needed to prove just cause before terminating the contract.","zh-TW":"公司需要在終止合約前證明正當理由。"}]', NULL, NULL, 4, 3765, NULL),
(3766, 'just transition', '/dʒʌst trænˈzɪʃən/', 'noun', '{"zh-TW":["公正轉型"],"en":["ensuring that the shift to a green economy is fair to workers and communities"]}', NULL, 'implement a just transition / just transition framework / just transition principles', '[{"en":"A just transition ensures that coal miners are not left behind in the energy shift.","zh-TW":"公正轉型確保煤礦工人在能源轉型中不被落下。"},{"en":"Labor unions advocate for just transition policies to protect jobs.","zh-TW":"勞工工會倡導公正轉型政策以保護就業。"}]', NULL, NULL, 5, 3766, NULL),
(3767, 'just-in-time', '/ˌdʒʌst ɪn ˈtaɪm/', 'noun', '{"zh-TW":["即時生產；零庫存管理"],"en":["an inventory strategy minimizing stock by ordering only as needed"]}', NULL, 'just-in-time manufacturing / just-in-time delivery / adopt just-in-time', '[{"en":"Just-in-time manufacturing reduced storage costs dramatically.","zh-TW":"即時生產大幅降低了倉儲成本。"},{"en":"The just-in-time system is vulnerable to supply chain disruptions.","zh-TW":"即時生產系統容易受到供應鏈中斷的影響。"}]', '{"abbreviation":"JIT"}', NULL, 4, 3767, NULL),
(3768, 'just-in-time delivery', '/ˌdʒʌst ɪn taɪm dɪˈlɪvəri/', 'noun', '{"zh-TW":["準時制交貨"],"en":["a logistics strategy delivering goods exactly when needed to minimize storage"]}', NULL, 'implement just-in-time delivery / just-in-time delivery system', '[{"en":"Just-in-time delivery reduces inventory holding costs significantly.","zh-TW":"準時制交貨顯著降低了庫存持有成本。"},{"en":"The factory runs on just-in-time delivery to avoid overproduction.","zh-TW":"工廠採用準時制交貨以避免生產過剩。"}]', '{"abbreviation":"JIT"}', NULL, 5, 3768, NULL),
(3769, 'justice', '/ˈdʒʌstɪs/', 'noun', '{"zh-TW":["正義；司法"],"en":["fairness; the legal system"]}', NULL, 'justice system / bring to justice', '[{"en":"They demand justice for the victims.","zh-TW":"他們要求為受害者伸張正義。"},{"en":"The criminal was brought to justice.","zh-TW":"罪犯被繩之以法。"}]', NULL, NULL, 3, 3769, NULL),
(3770, 'justify', '/ˈdʒʌstɪfaɪ/', 'verb', '{"zh-TW":["證明...合理；為...辯護"],"en":["to show that something is reasonable or right"]}', NULL, 'justify a decision/expense/action', '[{"en":"How can you justify such a large expense?","zh-TW":"你怎麼能證明這麼大的開支是合理的？"},{"en":"The results justify our investment.","zh-TW":"結果證明我們的投資是合理的。"}]', '{"noun":"justification","verb":"justify","adjective":"justifiable, justified"}', NULL, 3, 3770, 380),
(3771, 'juxtapose', '/ˈdʒʌkstəpəʊz/', 'verb', '{"zh-TW":["並置；並排比較"],"en":["to place side by side for contrast or comparison"]}', NULL, 'juxtapose two ideas / juxtapose data / juxtapose concepts', '[{"en":"The essay juxtaposes traditional and modern perspectives.","zh-TW":"文章並置傳統與現代觀點進行比較。"},{"en":"Juxtaposing the two charts reveals a clear trend.","zh-TW":"並排比較兩張圖表揭示了一個明顯的趨勢。"}]', '{"noun":"juxtaposition"}', NULL, 3, 3771, NULL),
(3772, 'Kanban', '/ˈkænbæn/', 'noun', '{"zh-TW":["看板；看板方法"],"en":["a visual workflow management system using cards on a board to track tasks"]}', NULL, 'Kanban board / Kanban method / Kanban workflow', '[{"en":"The team used a Kanban board to visualize work in progress.","zh-TW":"團隊使用看板視覺化進行中的工作。"},{"en":"Kanban helps identify bottlenecks in the workflow quickly.","zh-TW":"看板幫助快速識別工作流程中的瓶頸。"}]', NULL, NULL, 2, 3772, NULL),
(3773, 'keen', '/kiːn/', 'adjective', '{"zh-TW":["熱衷的；敏銳的"],"en":["eager or enthusiastic; sharp or acute"]}', NULL, 'keen interest / keen on / keen sense', '[{"en":"She is keen on learning new languages.","zh-TW":"她熱衷於學習新語言。"},{"en":"He has a keen eye for detail.","zh-TW":"他對細節有敏銳的眼光。"}]', '{"noun":"keenness","adjective":"keen","adverb":"keenly"}', NULL, 1, 3773, NULL),
(3774, 'keep', '/kiːp/', 'verb', '{"zh-TW":["保持；持續"],"en":["to continue to have","to remain in a state"]}', NULL, 'keep up / keep in mind', '[{"en":"Keep in mind the deadline is Friday.","zh-TW":"請記住截止日期是週五。"},{"en":"Keep up the good work.","zh-TW":"繼續保持好的表現。"}]', '{"verb":"keep","noun":"keeper"}', NULL, 1, 3774, NULL),
