(3776, 'key', '/kiː/', 'noun, adjective', '{"zh-TW":["鑰匙；關鍵","關鍵的"],"en":["a small metal instrument for opening locks; essential","of crucial importance"]}', NULL, 'key factor/role/issue / the key to success', '[{"en":"Communication is the key to a successful partnership.","zh-TW":"溝通是成功合作的關鍵。"},{"en":"She plays a key role in the organization.","zh-TW":"她在組織中扮演著關鍵角色。"}]', '{"noun":"key","adjective":"key"}', NULL, 1, 3776, NULL),
