(3778, 'key man insurance', '/kiː mæn ɪnˈʃʊərəns/', 'noun', '{"zh-TW":["關鍵人物保險"],"en":["life insurance on an essential employee whose death would harm the business"]}', NULL, 'purchase key man insurance / key man insurance payout', '[{"en":"The company took out key man insurance on its founder and CEO.","zh-TW":"公司對其創始人和CEO購買了關鍵人物保險。"},{"en":"Key man insurance proceeds can fund succession planning or business continuity.","zh-TW":"關鍵人物保險賠付可用於資助繼任規劃或業務連續性。"}]', NULL, NULL, 5, 3778, NULL),
(3779, 'key man risk', '/kiː mæn rɪsk/', 'noun', '{"zh-TW":["關鍵人物風險"],"en":["the risk arising from over-dependence on a critical individual in an organization"]}', NULL, 'manage key man risk / key man risk insurance', '[{"en":"The company purchased key man risk insurance on its founder.","zh-TW":"公司為其創辦人購買了關鍵人物風險保險。"},{"en":"Key man risk is reduced by developing succession plans and cross-training.","zh-TW":"通過制定接班計劃和交叉培訓可以降低關鍵人物風險。"}]', NULL, NULL, 4, 3779, NULL),
(3780, 'key metric', '/kiː ˈmetrɪk/', 'noun', '{"zh-TW":["關鍵指標"],"en":["an important measurement used to evaluate business performance"]}', NULL, 'define key metrics / track key metrics', '[{"en":"Revenue growth rate is a key metric for assessing business health.","zh-TW":"收入增長率是評估業務健康的關鍵指標。"},{"en":"Monthly reports highlight key metrics for senior management review.","zh-TW":"月度報告重點展示高級管理層審查的關鍵指標。"}]', NULL, NULL, 4, 3780, NULL),
