(3782, 'key risk indicator', '/kiː rɪsk ˈɪndɪkeɪtər/', 'noun', '{"zh-TW":["關鍵風險指標"],"en":["a metric used to measure potential exposure to risk"]}', NULL, 'monitor key risk indicators / set key risk indicators', '[{"en":"Key risk indicators are reviewed weekly by the risk committee.","zh-TW":"關鍵風險指標每週由風險委員會審查。"},{"en":"An increase in key risk indicators triggered an urgent review.","zh-TW":"關鍵風險指標的上升觸發了緊急審查。"}]', '{"abbreviation":"KRI"}', NULL, 5, 3782, NULL),
